<?php use App\Support\App;$u=App::requireAuth();$q=App::db()->prepare('SELECT id,label,is_active,last_used_at,created_at FROM api_keys WHERE user_id=? ORDER BY id DESC');$q->execute([$u['id']]);$rows=$q->fetchAll();$title='API Keys';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><div class="flex flex-col sm:flex-row justify-between sm:items-end gap-4"><div><h1 class="page-title">API keys</h1><p class="page-sub">Kelola credential untuk integrasi API.</p></div><button class="btn btn-dark" onclick="newKey()"><i data-lucide="plus"></i>Create API key</button></div><div class="saas-card mt-6 overflow-auto"><table class="w-full text-sm min-w-[600px]"><thead><tr><th>Label</th><th>Status</th><th>Last used</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="border-t" style="border-color:var(--line)"><td class="font-semibold"><?=htmlspecialchars($r['label'])?></td><td><span class="badge"><?=$r['is_active']?'ACTIVE':'REVOKED'?></span></td><td><?=htmlspecialchars($r['last_used_at']??'Never')?></td><td><?=htmlspecialchars($r['created_at'])?></td><td><?php if($r['is_active']):?><button class="btn !py-1 !px-2 text-xs" onclick="revokeKey(<?=$r['id']?>)">Revoke</button><?php endif?></td></tr><?php endforeach?></tbody></table></div><script>async function newKey(){let x=await Swal.fire({title:'Create API key',input:'text',inputLabel:'Label',inputValue:'Default API',showCancelButton:true});if(!x.isConfirmed)return;let r=await fetch('/api/api-keys/create',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':'<?=App::csrf()?>'},body:JSON.stringify({label:x.value})}),j=await r.json();if(j.ok)Swal.fire({title:'API key created',html:'<p class="text-sm">Copy sekarang. Key hanya ditampilkan sekali.</p><input class="swal2-input" value="'+j.key+'" readonly onclick="this.select()">',icon:'success'}).then(()=>location.reload());else Swal.fire('Error',j.message,'error')}async function revokeKey(id){let r=await fetch('/api/api-keys/revoke',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':'<?=App::csrf()?>'},body:JSON.stringify({id})}),j=await r.json();if(j.ok)location.reload()}</script><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>